  function addDateDays(value,days){if(!value)return'';const [y,m,d]=String(value).split('-').map(Number),dt=new Date(Date.UTC(y,m-1,d+Number(days||0)));return`${dt.getUTCFullYear()}-${String(dt.getUTCMonth()+1).padStart(2,'0')}-${String(dt.getUTCDate()).padStart(2,'0')}`;}
  function setFuelMode(mode='balance'){
    fuelViewMode=mode==='settlement'?'settlement':'balance';
    const isSettlement=fuelViewMode==='settlement';
    $('seaVibeFuelBalancePanel')?.classList.toggle('hidden',isSettlement);
    $('seaVibeFuelSettlementPanel')?.classList.toggle('hidden',!isSettlement);
    $('seaVibeFuelTopupBtn')?.classList.toggle('hidden',isSettlement);
    $('seaVibeFuelBalanceTab')?.classList.toggle('is-active',!isSettlement);
    $('seaVibeFuelSettlementTab')?.classList.toggle('is-active',isSettlement);
    $('seaVibeFuelBalanceTab')?.setAttribute('aria-selected',String(!isSettlement));
    $('seaVibeFuelSettlementTab')?.setAttribute('aria-selected',String(isSettlement));
    if(isSettlement){
      const rows=snap().fuelSettlements||[],last=rows[0]?.cutoffDate||'';
      const input=$('seaVibeFuelSettlementDate');
      if(input){
        input.max=localDateIso();
        input.min=last?addDateDays(last,1):'';
        const noOpenCutoff=Boolean(input.min&&input.max&&input.min>input.max);
        input.disabled=noOpenCutoff;
        if(noOpenCutoff){
          input.value='';
          showStatus('seaVibeFuelSettlementStatus',t('seaVibe.fuel.noOpenCutoffToday','لا يوجد تاريخ تسوية جديد متاح اليوم بعد آخر Cutoff معتمد.'),'info');
        }else if(!input.value||(input.min&&input.value<input.min)||input.value>input.max){
          input.value=input.max;
        }
      }
      renderFuelSettlementHistory();
    }
  }
  function settlementGateText(gate){const map={READY:t('seaVibe.fuel.settlementReady','التسوية جاهزة للاعتماد.'),HOLD_FUTURE_CUTOFF:t('seaVibe.fuel.settlementFuture','لا يمكن اختيار تاريخ تسوية مستقبلي.'),HOLD_CUTOFF_NOT_AFTER_LAST:t('seaVibe.fuel.settlementCutoffLocked','يجب أن يكون تاريخ التسوية بعد آخر Cutoff معتمد.'),HOLD_INVALID_WEIGHTS:t('seaVibe.fuel.settlementWeightsInvalid','نسب التوزيع غير صحيحة؛ يجب أن يكون مجموعها 100%.'),HOLD_PENDING_VALUATION:t('seaVibe.fuel.settlementPendingValuation','لا يمكن التسوية قبل اكتمال تقييم اللترات بسعر لتر صالح.'),HOLD_NO_ELIGIBLE_TRIPS:t('seaVibe.fuel.settlementNoTrips','لا توجد رحلات مؤهلة داخل فترة التسوية.'),HOLD_TRIP_FUEL_INCOMPLETE:t('seaVibe.fuel.settlementFuelIncomplete','توجد رحلات بلا تكلفة بنزين نظامية مكتملة.'),HOLD_ALREADY_ZERO:t('seaVibe.fuel.settlementAlreadyZero','الرصيد عند هذا التاريخ يساوي صفر بالفعل.'),HOLD_NEGATIVE_TRIP_FUEL_COST:t('seaVibe.fuel.settlementNegativeTripCost','التوزيع المقترح سيجعل تكلفة بنزين رحلة سالبة؛ لا يمكن الاعتماد.')};return map[gate]||gate||t('seaVibe.fuel.settlementNotReady','التسوية غير جاهزة للاعتماد.');}
  function renderFuelSettlementHistory(){const rows=snap().fuelSettlements||[],body=$('seaVibeFuelSettlementHistoryBody');if(!body)return;body.innerHTML=rows.length?rows.map(x=>`<tr><td>${esc(dateText(x.cutoffDate))}</td><td>${esc(x.previousCutoffDate?dateText(x.previousCutoffDate):'—')}</td><td class="sea-vibe-money">${esc(money(x.balanceBeforeValue))}</td><td class="sea-vibe-money">${esc(litersText(x.balanceBeforeLiters))}</td><td>${x.eligibleTripCount}</td><td>${new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(x.peopleWeightPct)}% / ${new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(x.hoursWeightPct)}%</td></tr>`).join(''):`<tr><td colspan="6" class="empty-cell">${esc(t('seaVibe.fuel.noSettlements','لا توجد تسويات بنزين معتمدة.'))}</td></tr>`;}
  function renderFuelSettlementPreview(data){fuelSettlementPreview=data||null;const root=$('seaVibeFuelSettlementPreview');if(!root)return;if(!data){root.classList.add('hidden');return;}root.classList.remove('hidden');$('seaVibeFuelSettlementPreviousCutoff').textContent=data.previousCutoffDate?dateText(data.previousCutoffDate):t('seaVibe.fuel.firstCutoff','أول تسوية');$('seaVibeFuelSettlementBalanceLiters').textContent=litersText(data.balanceLiters);$('seaVibeFuelSettlementBalanceValue').textContent=money(data.balanceValue);$('seaVibeFuelSettlementTripCount').textContent=String(data.eligibleTripCount||0);$('seaVibeFuelSettlementPeriod').textContent=`${data.periodStartDate?dateText(data.periodStartDate):t('seaVibe.fuel.fromBeginning','من بداية السجل')} — ${dateText(data.cutoffDate)}`;$('seaVibeFuelSettlementPopulation').textContent=`${Number(data.totalPeople||0)} ${t('seaVibe.fuel.peopleUnit','فرد')} / ${Number(data.totalHours||0)} ${t('seaVibe.common.hours','ساعات')}`;$('seaVibeFuelSettlementWeights').textContent=`${Number(data.peopleWeightPct||0).toFixed(0)}% / ${Number(data.hoursWeightPct||0).toFixed(0)}%`;$('seaVibeFuelSettlementUnitCosts').textContent=`${t('seaVibe.fuel.costPerPerson','تكلفة الفرد')}: ${money(data.valuePerPerson||0)} • ${t('seaVibe.fuel.costPerHour','تكلفة الساعة')}: ${money(data.valuePerHour||0)}`;const lines=Array.isArray(data.distribution)?data.distribution:[];$('seaVibeFuelSettlementPreviewBody').innerHTML=lines.length?lines.map(x=>`<tr><td><strong>${esc(x.tripSerial||'—')}</strong></td><td>${esc(dateText(x.tripDate))}</td><td>${Number(x.peopleCount||0)}</td><td>${Number(x.durationHours||0)} ${esc(t('seaVibe.common.hours','ساعات'))}</td><td class="sea-vibe-money">${esc(money(x.fuelCostBefore))}</td><td class="sea-vibe-money ${Number(x.adjustmentValue||0)>=0?'sea-vibe-profit-positive':'sea-vibe-profit-negative'}">${Number(x.adjustmentValue||0)>0?'+':''}${esc(money(x.adjustmentValue))}</td><td class="sea-vibe-money">${esc(money(x.fuelCostAfter))}</td><td class="sea-vibe-money ${Number(x.adjustmentLiters||0)>=0?'sea-vibe-profit-positive':'sea-vibe-profit-negative'}">${Number(x.adjustmentLiters||0)>0?'+':''}${esc(litersText(x.adjustmentLiters))}</td></tr>`).join(''):`<tr><td colspan="8" class="empty-cell">${esc(t('seaVibe.fuel.noDistribution','لا يوجد توزيع متاح لهذه المعاينة.'))}</td></tr>`;const ready=data.gate==='READY';$('seaVibeFuelSettlementApplyBtn').disabled=!ready;showStatus('seaVibeFuelSettlementStatus',settlementGateText(data.gate),ready?'success':'error');applyPermissions();}
  async function previewFuelSettlementUI(){try{showStatus('seaVibeFuelSettlementStatus',t('seaVibe.fuel.previewLoading','جاري حساب التسوية...'));const date=$('seaVibeFuelSettlementDate')?.value||'';const data=await window.SeaVibeService.previewFuelSettlement(date);renderFuelSettlementPreview(data);}catch(err){fuelSettlementPreview=null;$('seaVibeFuelSettlementPreview')?.classList.add('hidden');showStatus('seaVibeFuelSettlementStatus',err.message,'error');}}
