  function calculateFuelTopupLiters(){const value=Number($('seaVibeFuelTopupValueInput')?.value||0),unitPrice=Number($('seaVibeFuelTopupUnitPrice')?.value||0);return value>0&&unitPrice>0?Number((value/unitPrice).toFixed(3)):0;}
